package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();s.persist(new Employee(1,"Meenakshi",new Address("Main Road","Vizianagaram","AP","535001")));t.commit();System.out.println("Employee with embedded address persisted.");}HibernateUtil.getSessionFactory().close();}}